// The subset of the Codex app-server protocol the Codex adapter uses, hand-written from the bindings generated by
// `codex app-server generate-ts --experimental` with codex-cli 0.162.1 (v2 API). Wire format: JSON-RPC 2.0 without
// the `"jsonrpc"` field, one JSON object per line on stdio. Only the fields the adapter reads or sends are listed.

export type RequestId = string | number;

/** Client → server or server → client request; a notification has no `id`. */
export type RpcRequest = { id: RequestId; method: string; params?: unknown };
export type RpcNotification = { method: string; params?: unknown };
export type RpcResponse = {
  id: RequestId;
  result?: unknown;
  error?: { code: number; message: string; data?: unknown };
};
export type RpcMessage = RpcRequest | RpcNotification | RpcResponse;

export type InitializeParams = {
  clientInfo: { name: string; title: string | null; version: string };
  /** `experimentalApi` is required for `dynamicTools`. */
  capabilities: { experimentalApi: boolean; requestAttestation: boolean } | null;
};

export type AskForApproval = "untrusted" | "on-request" | "never";
export type SandboxMode = "read-only" | "workspace-write" | "danger-full-access";

/** Experimental (`capabilities.experimentalApi`): a function the model may call; answered via `item/tool/call`. */
export type DynamicToolSpec = {
  type: "function";
  name: string;
  description: string;
  inputSchema: unknown;
};

export type ThreadStartParams = {
  cwd: string;
  approvalPolicy: AskForApproval;
  sandbox: SandboxMode;
  /** Added to Codex's own instructions (`baseInstructions` would replace them). */
  developerInstructions: string;
  /** Per-thread overrides of `config.toml` keys. */
  config: Record<string, unknown>;
  dynamicTools?: DynamicToolSpec[];
};
export type ThreadStartResponse = { thread: { id: string } };

export type TurnStartParams = {
  threadId: string;
  input: { type: "text"; text: string; text_elements: [] }[];
};

export type ThreadItem =
  | {
      type: "agentMessage";
      id: string;
      text: string;
      phase: "commentary" | "final_answer" | null;
    }
  | {
      type: "commandExecution";
      id: string;
      command: string;
      cwd: string;
      status: string;
      aggregatedOutput: string | null;
      exitCode: number | null;
    }
  | {
      type: "fileChange";
      id: string;
      changes: { path: string; kind: { type: string }; diff: string }[];
      status: string;
    }
  | { type: string; id: string };

export type Turn = {
  id: string;
  items: ThreadItem[];
  status: "completed" | "interrupted" | "failed" | "inProgress";
  error: { message: string } | null;
  durationMs: number | null;
};
export type TurnStartResponse = { turn: Turn };
export type TurnCompletedNotification = { threadId: string; turn: Turn };
export type ItemNotification = { item: ThreadItem; threadId: string; turnId: string };

/** `item/commandExecution/requestApproval` */
export type CommandApprovalParams = {
  threadId: string;
  turnId: string;
  itemId: string;
  command?: string | null;
  cwd?: string | null;
};
/** `item/fileChange/requestApproval`: no paths; they are on the item announced by `item/started`. */
export type FileChangeApprovalParams = { threadId: string; turnId: string; itemId: string };
export type ApprovalDecision = "accept" | "decline";

/** `item/tool/call` (experimental dynamic tools). */
export type DynamicToolCallParams = {
  threadId: string;
  turnId: string;
  callId: string;
  tool: string;
  arguments: unknown;
};
export type DynamicToolCallResponse = {
  contentItems: { type: "inputText"; text: string }[];
  success: boolean;
};
